// Helper function to get images for a specific project
export function getProjectImages(projectId: string): ProjectImageImports {
  return projectImageImports[projectId] || {
    hero: null,
    demo: null,
    screenshots: []
  };
}

// Helper function to get image by filename for a project
export function getProjectImageByFilename(projectId: string, filename: string): StaticImageData | null {
  const projectFiles = projectImagesByFilename[projectId];
  return projectFiles ? (projectFiles[filename] || null) : null;
}

